/**
 * CheckoutPreview — Renders the REAL OrderPopup overlay (1:1 with production)
 * but with `checkoutMode="native"` so the Shopify CTA is replaced by
 * an inline address form + Stripe Payment Element + aggressive order bumps.
 *
 * Route: /checkout-preview
 *
 * Everything is identical to the production checkout overlay — upsells,
 * warehouse verification animation, gift progress bar, timer, trust badges —
 * except the "Proceed to Checkout" button is replaced with the native payment flow.
 */

import { useState, useCallback, useMemo } from "react";
import OrderPopup from "@/components/OrderPopup";
import { InlineNativeCheckout } from "@/checkout/InlineNativeCheckout";
import type { InlineCheckoutData } from "@/checkout/InlineNativeCheckout";
import type { OrderBumpItem, BundleUpgrade } from "@/checkout/CheckoutOrderBumps";

export default function CheckoutPreview() {
  const [isPopupOpen, setIsPopupOpen] = useState(true);
  const [completedPaymentId, setCompletedPaymentId] = useState<string | null>(null);

  // Default cart configuration for preview
  const selectedSize = "Standard" as const;
  const selectedQuantity = 4;
  const stockLevel = 23;
  const countdown = { hours: 2, minutes: 45, seconds: 30 };

  const handlePaymentComplete = useCallback((paymentIntentId: string) => {
    setCompletedPaymentId(paymentIntentId);
    console.log("[CheckoutPreview] Payment completed:", paymentIntentId);
  }, []);

  /**
   * AGGRESSIVE ORDER BUMPS — Inspired by top DTC funnels
   * 
   * Strategy:
   * 1. Lavender Sleep Spray — Low-cost impulse add ($12.99) pre-checked
   * 2. Premium Pillow Protector — Mid-price protection ($19.99) pre-checked  
   * 3. Extended 3-Year Warranty — High-margin protection ($24.99)
   * 
   * Pre-checked bumps use opt-out psychology (proven to increase AOV 15-30%)
   * Urgency text creates FOMO, social proof validates the choice
   */
  const orderBumps = useMemo<OrderBumpItem[]>(
    () => [
      {
        id: "lavender-spray",
        name: "Lavender Sleep Mist",
        description:
          "Calming pillow spray with pure lavender essential oil. Clinically shown to improve sleep onset by 37%.",
        price: 12.99,
        originalPrice: 24.99,
        savingsPercent: 48,
        badge: "MOST POPULAR",
        preChecked: true,
        urgencyText: "Only available at checkout — not sold separately",
        socialProof: "Added by 73% of customers this week",
      },
      {
        id: "pillow-protector",
        name: "Premium Pillow Protector",
        description:
          "Waterproof, hypoallergenic zippered cover. Extends pillow life by 3x and keeps it pristine.",
        price: 19.99,
        originalPrice: 34.99,
        savingsPercent: 43,
        badge: "RECOMMENDED",
        preChecked: true,
        urgencyText: "Exclusive checkout price — $15 off retail",
        socialProof: "4.8★ rated by 2,400+ customers",
      },
      {
        id: "extended-warranty",
        name: "3-Year Extended Warranty",
        description:
          "Full replacement coverage for any defect, flattening, or comfort issue. Zero questions asked.",
        price: 24.99,
        originalPrice: 49.99,
        savingsPercent: 50,
        preChecked: false,
        urgencyText: "Cannot be added after purchase",
        socialProof: "Claimed by 41% of orders",
      },
    ],
    []
  );

  // Render prop for the native checkout section
  const renderNativeCheckout = useCallback(
    (checkoutData: InlineCheckoutData) => (
      <InlineNativeCheckout
        checkoutData={checkoutData}
        onPaymentComplete={handlePaymentComplete}
        orderBumps={orderBumps}
      />
    ),
    [handlePaymentComplete, orderBumps]
  );

  return (
    <>
      {/* Background page — shown when popup is closed */}
      <div className="min-h-screen bg-[#FAF3EF] flex items-center justify-center p-4">
        <div className="text-center max-w-md">
          <div className="bg-amber-50 border border-amber-200 rounded-2xl p-5 mb-4">
            <h3 className="font-semibold text-base text-amber-900 mb-2">
              Checkout Preview Mode
            </h3>
            <p className="text-sm text-amber-700 mb-3">
              This page renders the exact production OrderPopup overlay with
              native Stripe checkout + aggressive order bumps replacing the
              Shopify redirect.
            </p>
            <p className="text-xs text-amber-600">
              Use test card{" "}
              <code className="bg-amber-100 px-1.5 py-0.5 rounded font-mono">
                4242 4242 4242 4242
              </code>{" "}
              with any future expiry and CVC.
            </p>
          </div>

          {completedPaymentId && (
            <div className="bg-green-50 border border-green-200 rounded-2xl p-4 mb-4">
              <p className="text-sm text-green-700 font-medium">
                Payment successful!
              </p>
              <p className="text-xs text-green-600 mt-1 font-mono">
                {completedPaymentId}
              </p>
            </div>
          )}

          <button
            onClick={() => {
              setIsPopupOpen(true);
              setCompletedPaymentId(null);
            }}
            className="px-8 py-3.5 bg-[#e63946] text-white rounded-full font-semibold text-base hover:bg-[#d62839] transition-colors shadow-lg shadow-red-200/40"
          >
            {completedPaymentId ? "Test Again" : "Open Checkout"}
          </button>
        </div>
      </div>

      {/* The actual OrderPopup — 1:1 with production, but with native checkout mode */}
      <OrderPopup
        isOpen={isPopupOpen}
        onClose={() => setIsPopupOpen(false)}
        selectedSize={selectedSize}
        selectedQuantity={selectedQuantity}
        stockLevel={stockLevel}
        countdown={countdown}
        checkoutMode="native"
        onNativePaymentComplete={handlePaymentComplete}
        renderNativeCheckout={renderNativeCheckout}
      />
    </>
  );
}
